SELECT "accountid", "sk_brokerid", "sk_customerid", "status", "accountdesc", "taxstatus", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY accountid, effectivedate) AS int) AS "sk_accountid" FROM (SELECT TRY_CAST((CAST(a.CA_ID AS INTEGER)) AS int) AS "accountid", TRY_CAST((COALESCE(CAST(a.CA_B_ID AS INT), 0)) AS int) AS "sk_brokerid", TRY_CAST((CAST(c.C_ID AS INTEGER)) AS int) AS "sk_customerid", TRY_CAST((CASE WHEN act.ActionType = 'CLOSEACCT' THEN 'closed' ELSE 'active' END) AS char(10)) AS "status", TRY_CAST((a.CA_NAME) AS varchar(50)) AS "accountdesc", TRY_CAST((CAST(COALESCE(a.CA_TAX_ST, 0) AS INTEGER)) AS int) AS "taxstatus", TRY_CAST((TRUE) AS boolean) AS "iscurrent", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "batchid", TRY_CAST((CAST(SUBSTRING(act.ActionTS, 1, 10) AS DATE)) AS date) AS "effectivedate", TRY_CAST((CASE WHEN act.ActionType = 'CLOSEACCT' THEN CAST(act.ActionTS AS DATE) ELSE CAST('9999-12-31' AS DATE) END) AS date) AS "enddate" FROM AccountXML AS a INNER JOIN CustomerXML AS c ON a.Customer_Id = c.Customer_Id INNER JOIN ActionXML AS act ON c.Action_Id = act.Action_Id WHERE act.ActionType IN ('NEW','ADDACCT','UPDACCT','CLOSEACCT'))
